/* Modexa interactions: restrained motion, accessibility first */
(()=>{'use strict';
const reduce=window.matchMedia('(prefers-reduced-motion: reduce)'),fine=window.matchMedia('(hover:hover) and (pointer:fine)').matches,body=document.body;
const ambient=document.createElement('div');ambient.className='mx-ambient';ambient.setAttribute('aria-hidden','true');body.prepend(ambient);
const progress=document.createElement('div');progress.className='mx-progress';progress.setAttribute('aria-hidden','true');body.append(progress);
let queued=false;function update(){const max=document.documentElement.scrollHeight-innerHeight;progress.style.transform='scaleX('+Math.max(0,Math.min(1,max?scrollY/max:0))+')';queued=false}
addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update,{passive:true});update();
const reveals=[...document.querySelectorAll('.reveal')];reveals.forEach((el,i)=>el.style.setProperty('--mx-delay',Math.min(i%4,3)*55+'ms'));
document.querySelectorAll('.card,.step-card,.link-card,.panel,.community-panel,.cta,.platform,.core').forEach(el=>el.classList.add('mx-card'));
if(!reduce.matches&&fine){const canvas=document.createElement('canvas');canvas.className='mx-particles';canvas.setAttribute('aria-hidden','true');body.append(canvas);const ctx=canvas.getContext('2d');let w=0,h=0,ps=[],last=0;function resize(){const d=Math.min(devicePixelRatio||1,2);w=innerWidth;h=innerHeight;canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);ctx.setTransform(d,0,0,d,0,0)}resize();addEventListener('resize',resize,{passive:true});addEventListener('pointermove',e=>{const now=performance.now();if(now-last<55)return;last=now;ps.push({x:e.clientX,y:e.clientY,r:1+Math.random()*1.2,a:.22,life:1,vx:(Math.random()-.5)*.25,vy:(Math.random()-.5)*.25})},{passive:true});let visible=true;document.addEventListener('visibilitychange',()=>visible=!document.hidden);function draw(){requestAnimationFrame(draw);if(!visible)return;ctx.clearRect(0,0,w,h);for(let i=ps.length-1;i>=0;i--){const p=ps[i];p.x+=p.vx;p.y+=p.vy;p.life-=.035;p.a*=.97;if(p.life<=0){ps.splice(i,1);continue}ctx.fillStyle='rgba(196,204,255,'+p.a+')';ctx.beginPath();ctx.arc(p.x,p.y,p.r*p.life,0,Math.PI*2);ctx.fill()}}requestAnimationFrame(draw)}
if(!reduce.matches&&'IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.08});reveals.forEach(el=>io.observe(el))}else reveals.forEach(el=>el.classList.add('in'));
if(!reduce.matches)document.querySelectorAll('a.btn,.navcta').forEach(el=>el.addEventListener('click',e=>{const r=el.getBoundingClientRect(),s=document.createElement('span');s.className='mx-ripple';s.style.left=(e.clientX-r.left)+'px';s.style.top=(e.clientY-r.top)+'px';el.append(s);setTimeout(()=>s.remove(),700)}));
})();